CODIGOS_CANONICOS: Set[str] = set(CATALOGO_REGLAS.keys())
_CODIGOS_CANONICOS_LOW: Dict[str, str] = {c.lower(): c for c in CODIGOS_CANONICOS}

# Registrar alias retrocompatibles para códigos anteriores que no colisionen
for _cod_ant, _cod_n in MAPA_RENUMERACION.items():
    if _cod_ant not in CATALOGO_REGLAS and _cod_n in CATALOGO_REGLAS:
        CATALOGO_REGLAS[_cod_ant] = CATALOGO_REGLAS[_cod_n]


def normalizar_codigo(codigo: str) -> str:
    """Normaliza un código de regla a su versión canónica nueva."""
    cod = codigo.strip()
    if not cod.startswith("0x"):
        return cod
    cod_h = cod if cod.endswith("h") else cod + "h"
    cod_low = cod_h.lower()
    # Si ya es un código canónico del catálogo nuevo, preservarlo
    if cod_low in _CODIGOS_CANONICOS_LOW:
        return _CODIGOS_CANONICOS_LOW[cod_low]
    # Si es un código anterior de renumeración, traducir
    if cod_h in MAPA_RENUMERACION:
        return MAPA_RENUMERACION[cod_h]
    for k, v in MAPA_RENUMERACION.items():
        if k.lower() == cod_low:
            return v
    return cod_h


def obtener_regla(codigo: str) -> Optional[Dict[str, Any]]:
    """Busca una regla por código nuevo, viejo o alias de forma insensible a mayúsculas."""
    cod = codigo.strip()
    cod_low = cod.lower()
    cod_h = cod_low + "h" if (cod_low.startswith("0x") and not cod_low.endswith("h")) else cod_low

    # 1. Búsqueda directa o normalizada
    if cod in CATALOGO_REGLAS:
        return CATALOGO_REGLAS[cod]
    cod_norm = normalizar_codigo(cod)
    if cod_norm in CATALOGO_REGLAS:
        return CATALOGO_REGLAS[cod_norm]

    # 2. Búsqueda por coincidencia de campos
    for k, info in CATALOGO_REGLAS.items():
        k_low = k.lower()
        if k_low in (cod_low, cod_h):
            return info
        if info.get("codigo", "").lower() in (cod_low, cod_h):
            return info
        if info.get("codigo_anterior", "").lower() in (cod_low, cod_h):
            return info
        if info.get("alias", "").lower() in (cod_low, cod_h):
            return info

    return None


def cargar_reglas_desde_apunte(directorio_apunte: Optional[Path] = None) -> Dict[str, Dict[str, Any]]:
    """Carga y sincroniza las reglas canónicas desde renumeracion.json y apunte/reglas."""
    rutas_candidatas = [
        Path(os.environ.get("P1_REGLAS_DIR", "")) if os.environ.get("P1_REGLAS_DIR") else None,
        directorio_apunte,
        Path("/home/mrtin/dev/tools/apunte/reglas"),
        Path("/home/mrtin/dev/edu-sitios/p1-apunte/reglas"),
        Path.cwd().parents[0] / "apunte" / "reglas",
        Path.cwd().parents[1] / "edu-sitios" / "p1-apunte" / "reglas",
        Path(__file__).resolve().parents[4] / "apunte" / "reglas",
    ]
    dir_valido: Optional[Path] = None
    for r in rutas_candidatas:
        if r and r.is_dir():
            dir_valido = r
            break

    if not dir_valido:
        return CATALOGO_REGLAS

    # Sincronización desde renumeracion.json si existe
    json_file = dir_valido / "renumeracion.json"
    if json_file.is_file():
        try:
            data = json.loads(json_file.read_text(encoding="utf-8"))
            for r in data.get("reglas", []):
                cn = r.get("codigo_nuevo")
                if cn in CATALOGO_REGLAS:
                    CATALOGO_REGLAS[cn]["titulo"] = r.get("titulo", CATALOGO_REGLAS[cn]["titulo"])
                    CATALOGO_REGLAS[cn]["archivo_apunte"] = r.get("archivo", CATALOGO_REGLAS[cn].get("archivo_apunte", ""))
                    if "directorio" in r:
                        CATALOGO_REGLAS[cn]["directorio"] = r["directorio"]
        except Exception:
            pass

    return CATALOGO_REGLAS


# Carga inicial
cargar_reglas_desde_apunte()
